    if (smolOk.ok) {
      return _PickOutcome(
        ok: true,
        error: null,
        noWork: smolOk.noWork,
        fallback: 'smol=$smolLabel',
        summary: smolOk.summary,
        hiddenRecords: smolOk.hiddenRecords,
        summarizedMessages: smolOk.summarizedMessages,
