    return _PickOutcome(
      ok: true,
      error: null,
      noWork: mainOk.noWork,
      fallback: 'main=$mainLabel',
      summary: mainOk.summary,
      hiddenRecords: mainOk.hiddenRecords,
      summarizedMessages: mainOk.summarizedMessages,
    );
  }
  return _PickOutcome(
    ok: false,
    error: mainOk.error,
    noWork: false,
    fallback: null,
    summary: null,
